import assert from 'node:assert';
import { load } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // The original condition was 'value[0] === "-" || value[0] === "+"'
    // which correctly handles both minus and plus signs.
    // The changed condition 'value[0] === "-" && value[0] === "+"'
    // is always false because a character cannot be both '-' and '+'
    // This means negative numbers like "-42" will not be properly parsed
    // as they will fail to enter the sign handling block.
    const invalidInput = "-42";
    try {
      load(invalidInput);
      assert.fail('Should have thrown for negative numbers');
    } catch (e) {
      assert.ok(e instanceof Error, 'Should throw an error');
    }
  });
});

