import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // The change incorrectly restricts the explicit float pattern to require
    // a leading + or - sign, but the YAML spec allows optional signs in explicit
    // floats. The original pattern correctly allowed both forms.
    // This test checks that the patch breaks valid YAML with explicit floats.
    const data = "---
- 1.23
- +1.23
- -1.23
- .123
- +.123
- -.123
- 1.23e4
- +1.23e4
- -1.23e4
- .123e4
- +.123e4
- -.123e4
";
    const result = load(data);
    assert.strictEqual(result.length, 12);
    assert.strictEqual(result[0], 1.23);
    assert.strictEqual(result[1], 1.23);
    assert.strictEqual(result[2], -1.23);
    assert.strictEqual(result[3], 0.123);
    assert.strictEqual(result[4], 0.123);
    assert.strictEqual(result[5], -0.123);
    assert.strictEqual(result[6], 12300);
    assert.strictEqual(result[7], 12300);
    assert.strictEqual(result[8], -12300);
    assert.strictEqual(result[9], 1230);
    assert.strictEqual(result[10], 1230);
    assert.strictEqual(result[11], -1230);
  });
});

