import assert from 'node:assert';
import { load, dump } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    const input = { a: 1, b: 2 };
    const output = dump(input);
    const parsed = load(output);
    assert.deepEqual(parsed, input);

    // Test that the change breaks the ability to distinguish plain objects
    const customObj = Object.create(null);
    customObj.a = 1;
    const output2 = dump(customObj);
    const parsed2 = load(output2);

    // This should be true if the original implementation is correct
    // The patched version will incorrectly return true for Object.create(null)
    assert.strictEqual(parsed2.a, 1);
  });
});

