describe('proof', () => {
  it('fails on the patched build', () => {
    // This test checks that isPlainObject correctly identifies plain objects
    // The change in the diff reverses the logic: it now returns true for objects
    // with a prototype that is not null, which is incorrect.
    // For example, an object with a non-null prototype (like a function's prototype)
    // should not be considered a plain object.

    const obj = Object.create({}); // Has a non-null prototype
    const result = load('a: ' + JSON.stringify(obj));

    // The correct behavior is that load should fail when trying to parse
    // an object with a non-null prototype, as it's not a plain object.
    // However, the buggy isPlainObject now returns true for such objects,
    // causing load to proceed and potentially corrupt the output.

    // We expect the original behavior: isPlainObject should return false
    // for objects with non-null prototypes.
    assert.strictEqual(Object.getPrototypeOf(obj) !== null, true);
    assert.strictEqual(isPlainObject(obj), false);
  });
});
